(function () {
  const canvas = document.getElementById('confetti-canvas');
  const ctx = canvas.getContext('2d');
  const colors = ['#ff6fb5', '#8a4fff', '#ffc94d', '#5ad1ff', '#ff8a3d'];

  let width, height;
  function resize() {
    width = canvas.width = window.innerWidth;
    height = canvas.height = window.innerHeight;
  }
  window.addEventListener('resize', resize);
  resize();

  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function makePiece(burst) {
    return {
      x: burst ? width / 2 + (Math.random() - 0.5) * 120 : Math.random() * width,
      y: burst ? height * 0.55 + (Math.random() - 0.5) * 40 : -20 - Math.random() * height,
      size: 6 + Math.random() * 6,
      color: colors[Math.floor(Math.random() * colors.length)],
      speedY: burst ? -(4 + Math.random() * 6) : 1 + Math.random() * 1.5,
      speedX: burst ? (Math.random() - 0.5) * 10 : (Math.random() - 0.5) * 1,
      gravity: burst ? 0.25 : 0,
      rotation: Math.random() * 360,
      spin: (Math.random() - 0.5) * 10,
      life: burst ? 90 + Math.random() * 30 : Infinity,
    };
  }

  let ambient = [];
  const AMBIENT_COUNT = 45;
  if (!reduceMotion) {
    for (let i = 0; i < AMBIENT_COUNT; i++) ambient.push(makePiece(false));
  }

  let burstPieces = [];

  function drawPiece(p) {
    ctx.save();
    ctx.translate(p.x, p.y);
    ctx.rotate((p.rotation * Math.PI) / 180);
    ctx.fillStyle = p.color;
    ctx.fillRect(-p.size / 2, -p.size / 4, p.size, p.size / 2);
    ctx.restore();
  }

  function tick() {
    ctx.clearRect(0, 0, width, height);

    ambient.forEach((p) => {
      p.y += p.speedY;
      p.x += p.speedX;
      p.rotation += p.spin;
      if (p.y > height + 20) {
        p.y = -20;
        p.x = Math.random() * width;
      }
      drawPiece(p);
    });

    burstPieces = burstPieces.filter((p) => p.life > 0);
    burstPieces.forEach((p) => {
      p.speedY += p.gravity;
      p.y += p.speedY;
      p.x += p.speedX;
      p.rotation += p.spin;
      p.life -= 1;
      drawPiece(p);
    });

    requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);

  function burstConfetti() {
    for (let i = 0; i < 120; i++) burstPieces.push(makePiece(true));
  }

  // ---------- Birthday lock / countdown ----------
  // The surprise opens on Nov 14, 2026 (local time) and stays open after that.
  const REVEAL_DATE = new Date(2026, 10, 14, 0, 0, 0, 0);

  // The celebration markup is not present in the page source and is only
  // decoded and inserted once the birthday date actually arrives, so it
  // can't be read by viewing source / dev tools before the reveal.
  const CELEBRATION_B64 =
    '';

  function decodeCelebration(b64) {
    const binary = atob(b64);
    const percentEncoded = binary
      .split('')
      .map((c) => '%' + c.charCodeAt(0).toString(16).padStart(2, '0'))
      .join('');
    return decodeURIComponent(percentEncoded);
  }

  function revealLetterOnScroll() {
    const letter = document.querySelector('.letter');
    if (!letter) return;
    if (!('IntersectionObserver' in window) || reduceMotion) {
      letter.classList.add('visible');
      return;
    }
    const observer = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting) {
        letter.classList.add('visible');
        observer.disconnect();
      }
    }, { threshold: 0.15 });
    observer.observe(letter);
  }

  // ---------- 23 vueltas al sol ----------
  const BIRTH_DATE = new Date(2003, 10, 14, 0, 0, 0, 0);
  const MET_DATE = new Date(2023, 4, 1, 0, 0, 0, 0); // aproximada
  const HEART_BPM = 75;
  const EARTH_KM_PER_SEC = 29.78;

  function sunValues(now) {
    const ms = now - BIRTH_DATE;
    return {
      days: Math.floor(ms / 86400000),
      beats: (ms / 60000) * HEART_BPM,
      km: (ms / 1000) * EARTH_KM_PER_SEC,
      known: Math.floor((now - MET_DATE) / 86400000),
    };
  }

  function formatNumber(n) {
    return Math.floor(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  }

  function startSunStats() {
    const section = document.querySelector('.sun-section');
    if (!section) return;
    const fields = Array.from(section.querySelectorAll('[data-stat]'));
    const COUNT_UP_MS = 2600;
    let start = null;

    function frame(t) {
      if (start === null) start = t;
      const progress = reduceMotion ? 1 : Math.min(1, (t - start) / COUNT_UP_MS);
      const ease = 1 - Math.pow(1 - progress, 3);
      const values = sunValues(new Date());
      fields.forEach((el) => {
        el.textContent = formatNumber(values[el.dataset.stat] * ease);
      });
      if (progress === 1) section.classList.add('done');
      requestAnimationFrame(frame);
    }

    function begin() {
      section.classList.add('visible');
      requestAnimationFrame(frame);
    }

    if (!('IntersectionObserver' in window)) {
      begin();
      return;
    }
    const observer = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting) {
        observer.disconnect();
        begin();
      }
    }, { threshold: 0.3 });
    observer.observe(section);
  }

  // ---------- Pedí un deseo ----------
  function unlockWish() {
    const section = document.getElementById('wish-section');
    if (!section || !section.hidden) return;
    section.hidden = false;
    setTimeout(() => {
      section.scrollIntoView({ behavior: reduceMotion ? 'auto' : 'smooth', block: 'center' });
    }, 1400);
  }

  function setupWish() {
    const cake = document.getElementById('wish-cake');
    if (!cake) return;
    cake.addEventListener('click', () => {
      if (cake.classList.contains('blown')) return;
      cake.classList.add('blown');
      cake.disabled = true;
      setTimeout(() => {
        burstConfetti();
        document.getElementById('wish-done').classList.add('show');
      }, 500);
      setTimeout(openWishModal, 2200);
    });

    const modal = document.getElementById('wish-modal');
    const closeBtn = document.getElementById('wish-modal-close');

    function onKey(e) {
      if (e.key === 'Escape') closeWishModal();
    }

    function openWishModal() {
      // Move to <body> so it stays fixed to the screen, not to the page section.
      if (modal.parentNode !== document.body) document.body.appendChild(modal);
      modal.hidden = false;
      requestAnimationFrame(() => modal.classList.add('show'));
      document.addEventListener('keydown', onKey);
      closeBtn.focus({ preventScroll: true });
      burstConfetti();
    }

    function closeWishModal() {
      modal.classList.remove('show');
      document.removeEventListener('keydown', onKey);
      setTimeout(() => { modal.hidden = true; }, 400);
    }

    closeBtn.addEventListener('click', closeWishModal);
    modal.addEventListener('click', (e) => {
      if (e.target === modal) closeWishModal();
    });
  }

  // ---------- Atrapá 23 corazones ----------
  function setupHeartGame() {
    const box = document.getElementById('game-box');
    if (!box) return;
    const countEl = document.getElementById('game-count');
    const startOverlay = document.getElementById('game-start');
    const winOverlay = document.getElementById('game-win');
    const GOAL = 23;
    const HEARTS = ['💖', '💗', '💜', '💕', '❤️'];

    let hearts = [];
    let count = 0;
    let running = false;
    let spawnTimer = null;
    let lastTime = 0;

    function spawnHeart() {
      if (!running) return;
      const size = 48;
      const el = document.createElement('span');
      el.className = 'game-heart';
      el.textContent = HEARTS[Math.floor(Math.random() * HEARTS.length)];
      const heart = {
        el,
        x: Math.random() * (box.clientWidth - size),
        y: -size,
        speed: box.clientHeight / (2600 + Math.random() * 1600),
        phase: Math.random() * Math.PI * 2,
        caught: false,
      };
      el.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        catchHeart(heart);
      });
      box.appendChild(el);
      hearts.push(heart);
    }

    function catchHeart(heart) {
      if (heart.caught || !running) return;
      heart.caught = true;
      heart.el.classList.add('caught');
      setTimeout(() => heart.el.remove(), 350);
      count += 1;
      countEl.textContent = count;
      if (count >= GOAL) win();
    }

    function frame(t) {
      if (!running) return;
      const dt = lastTime ? Math.min(50, t - lastTime) : 16;
      lastTime = t;
      const limit = box.clientHeight + 10;
      hearts = hearts.filter((h) => {
        if (h.caught) return false;
        h.y += h.speed * dt;
        const sway = Math.sin(t / 400 + h.phase) * 10;
        h.el.style.transform = 'translate(' + (h.x + sway) + 'px,' + h.y + 'px)';
        if (h.y > limit) {
          h.el.remove();
          return false;
        }
        return true;
      });
      requestAnimationFrame(frame);
    }

    function clearHearts() {
      hearts.forEach((h) => h.el.remove());
      hearts = [];
    }

    function start() {
      count = 0;
      countEl.textContent = '0';
      startOverlay.hidden = true;
      winOverlay.hidden = true;
      box.classList.add('playing');
      running = true;
      lastTime = 0;
      spawnHeart();
      spawnTimer = setInterval(spawnHeart, 520);
      requestAnimationFrame(frame);
    }

    function win() {
      running = false;
      clearInterval(spawnTimer);
      setTimeout(clearHearts, 300);
      box.classList.remove('playing');
      winOverlay.hidden = false;
      burstConfetti();
      unlockWish();
    }

    document.getElementById('game-start-btn').addEventListener('click', start);
    document.getElementById('game-again').addEventListener('click', start);
  }

  const countdownScreen = document.getElementById('countdown-screen');
  const celebration = document.getElementById('celebration');
  const cdDays = document.getElementById('cd-days');
  const cdHours = document.getElementById('cd-hours');
  const cdMins = document.getElementById('cd-mins');
  const cdSecs = document.getElementById('cd-secs');

  function isRevealed(now) {
    return now >= REVEAL_DATE;
  }

  function pad(n) {
    return String(n).padStart(2, '0');
  }

  function revealCelebration() {
    if (countdownTimer) clearInterval(countdownTimer);
    if (!celebration.dataset.filled) {
      celebration.innerHTML = decodeCelebration(CELEBRATION_B64);
      celebration.dataset.filled = 'true';
      revealLetterOnScroll();
      startSunStats();
      setupHeartGame();
      setupWish();
    }
    countdownScreen.hidden = true;
    celebration.hidden = false;
    burstConfetti();
  }

  let countdownTimer = null;

  function startCountdown() {
    function tick() {
      const now = new Date();
      if (isRevealed(now)) {
        revealCelebration();
        return;
      }
      const diff = REVEAL_DATE - now;
      const totalSeconds = Math.floor(diff / 1000);
      const days = Math.floor(totalSeconds / 86400);
      const hours = Math.floor((totalSeconds % 86400) / 3600);
      const mins = Math.floor((totalSeconds % 3600) / 60);
      const secs = totalSeconds % 60;
      cdDays.textContent = pad(days);
      cdHours.textContent = pad(hours);
      cdMins.textContent = pad(mins);
      cdSecs.textContent = pad(secs);
    }

    tick();
    countdownTimer = setInterval(tick, 1000);
  }

  if (window.FORCE_REVEAL === true || isRevealed(new Date())) {
    revealCelebration();
  } else {
    startCountdown();
  }
})();
